+                .bindLifecycleTo(this);
+    }
+
+    private void addEditListeners() {
+        nameField.addValueChangeListener(event -> {
+            enableSendAfterEdit();
+            clearError(nameField);
+        });
+        emailField.addValueChangeListener(event -> {
+            enableSendAfterEdit();
+            clearError(emailField);
+        });
+        phoneField.addValueChangeListener(event -> enableSendAfterEdit());
+        messageField.addValueChangeListener(event -> {
+            enableSendAfterEdit();
+            clearError(messageField);
+        });
+    }
+
+    private void enableSendAfterEdit() {
+        sendButton.setEnabled(true);
+    }
+
+    private void sendMessage() {
+        if (!sendButton.isEnabled() || getUI().map(ui -> ui.hasModalComponent()).orElse(false)) {
+            return;
+        }
+
+        boolean valid = true;
+        String name = nameField.getValue();
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        String message = messageField.getValue();
+
+        if (name == null || name.isBlank()) {
+            setError(nameField, "Name is required");
+            valid = false;
+        } else {
+            clearError(nameField);
+        }
+
+        if (email != null && !email.isBlank() && emailField.getDefaultValidator().apply(email, null).isError()) {
+            setError(emailField, "Enter a valid e-mail address");
+            valid = false;
+        } else if ((email == null || email.isBlank()) && (phone == null || phone.isBlank())) {
+            setError(emailField, "Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            clearError(emailField);
+        }
+
+        if (message == null || message.isBlank()) {
+            setError(messageField, "Message is required");
+            valid = false;
+        } else if (message.length() > 500) {
+            setError(messageField, "Message must be at most 500 characters");
+            valid = false;
+        } else {
+            clearError(messageField);
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name, email, phone, message, Instant.now()));
+        messageGrid.setItems(messageStore.newestFirst());
+        Notification.show("Message sent");
+
+        clearError(nameField);
+        clearError(emailField);
+        clearError(messageField);
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        sendButton.setEnabled(false);
+    }
