+        field.setInvalid(true);
+    }
+
+    private static void setError(TextArea field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private static void clearError(TextField field) {
+        field.setInvalid(false);
+    }
+
+    private static void clearError(EmailField field) {
+        field.setInvalid(false);
+    }
+
+    private static void clearError(TextArea field) {
+        field.setInvalid(false);
+    }
